import React from 'react';
import { useApp } from '../context/AppContext';
import { Star, Award, ShoppingCart } from 'lucide-react';
import LazyImage from './LazyImage';
import CountdownTimer from './CountdownTimer';

const ProductCard = ({ product, onNavigateProduct }) => {
  const { addToCart, currentUser } = useApp();

  if (!product) return null;

  // Flash Sale Engine Check
  const isFlashSale = product.flashSale?.isActive && new Date(product.flashSale.endTime) > new Date();
  const price = isFlashSale ? product.flashSale.price : (product.price || 0);
  const originalPrice = product.originalPrice || (isFlashSale ? product.price : price);
  const discountPercent = originalPrice > 0 ? Math.round(((originalPrice - price) / originalPrice) * 100) : 0;

  // Dynamic earnings display
  const userEarningsCoins = Math.round(price * (product.userCommissionRate || 0));
  const influencerEarningsCash = Math.round(price * (product.influencerCommissionRate || 0));

  const handleAddToCart = (e) => {
    e.stopPropagation();
    addToCart(product);
  };

  return (
    <div className="card product-card" style={styles.card} onClick={() => onNavigateProduct(product.id)}>
      {/* Product Image */}
      <div className="product-card-image-wrapper" style={styles.imageWrapper}>
        {/* Sales Boost: Bestseller / Trending Badges */}
        {product.badge === 'bestseller' || (!product.badge && product.rating >= 4.7) ? (
          <div style={{ position: 'absolute', top: '12px', left: '12px', backgroundColor: '#ef4444', color: 'white', fontSize: '10px', fontWeight: '800', padding: '4px 8px', borderRadius: '4px', zIndex: 2, display: 'flex', alignItems: 'center', gap: '4px', boxShadow: '0 2px 4px rgba(239, 68, 68, 0.3)' }}>
            🔥 BESTSELLER
          </div>
        ) : product.badge === 'trending' || (!product.badge && product.rating >= 4.4) ? (
          <div style={{ position: 'absolute', top: '12px', left: '12px', backgroundColor: '#10b981', color: 'white', fontSize: '10px', fontWeight: '800', padding: '4px 8px', borderRadius: '4px', zIndex: 2, display: 'flex', alignItems: 'center', gap: '4px', boxShadow: '0 2px 4px rgba(16, 185, 129, 0.3)' }}>
            📈 TRENDING
          </div>
        ) : product.badge === 'new' ? (
          <div style={{ position: 'absolute', top: '12px', left: '12px', backgroundColor: '#8b5cf6', color: 'white', fontSize: '10px', fontWeight: '800', padding: '4px 8px', borderRadius: '4px', zIndex: 2, display: 'flex', alignItems: 'center', gap: '4px', boxShadow: '0 2px 4px rgba(139, 92, 246, 0.3)' }}>
            ✨ NEW ARRIVAL
          </div>
        ) : null}
        
        <LazyImage src={product.image} alt={product.name} style={styles.image} />
      </div>

      {/* Info Content */}
      <div className="product-card-info" style={styles.info}>
        <h4 className="product-card-name" style={styles.name} title={product.name}>
          {product.name}
        </h4>

        {/* Rating and Reviews */}
        <div className="product-card-rating-row" style={styles.ratingRow}>
          <span className="rating-tag">
            {product.rating} <Star size={10} fill="white" />
          </span>
          <span style={styles.reviewsCount}>({product.reviewsCount})</span>
          
          {/* Custom A-Assured Badge */}
          <div className="product-card-assured-badge" style={{ 
            marginLeft: 'auto', 
            display: 'inline-flex', 
            alignItems: 'center', 
            height: '16px', 
            background: 'linear-gradient(135deg, #1e3a8a 0%, #2874f0 100%)', 
            color: 'white', 
            borderRadius: '2px', 
            padding: '0 5px', 
            fontSize: '8px', 
            fontWeight: '900', 
            fontStyle: 'italic',
            boxShadow: '0 1px 2px rgba(0,0,0,0.05)'
          }}>
            A-Assured <span style={{ color: '#ffe500', marginLeft: '2px' }}>★</span>
          </div>
        </div>

        {/* Pricing */}
        <div className="product-card-price-row" style={styles.priceRow}>
          <span style={styles.price}>₹{(price).toLocaleString('en-IN')}</span>
          <span style={styles.originalPrice}>₹{(originalPrice).toLocaleString('en-IN')}</span>
          <span style={styles.discount}>{discountPercent}% off</span>
        </div>

        {/* Flash Sale Urgency Timer */}
        {isFlashSale && (
          <div style={{ marginTop: '4px', marginBottom: '8px' }}>
            <CountdownTimer endTime={product.flashSale.endTime} compact={true} />
          </div>
        )}

        {/* Dynamic Affiliate / Referral Earning Banner */}
        <div className="product-card-reward-banner" style={styles.rewardBanner}>
          <Award size={14} color="var(--primary-color)" style={{ flexShrink: 0 }} />
          <div style={styles.rewardText}>
            {currentUser && currentUser.isInfluencer ? (
              <span>Earn <strong style={{ color: 'var(--success)' }}>₹{influencerEarningsCash}</strong> cash</span>
            ) : (
              <span>Earn <strong style={{ color: '#e68f00' }}>{userEarningsCoins}</strong> Coins</span>
            )}
          </div>
        </div>

        {/* Quick Add To Cart */}
        <button className="product-add-to-cart-btn" style={styles.addBtn} onClick={handleAddToCart}>
          <ShoppingCart size={14} /> Add to Cart
        </button>
      </div>
    </div>
  );
};

const styles = {
  card: {
    backgroundColor: 'white',
    borderRadius: '20px',
    border: '1px solid #f1f5f9',
    overflow: 'hidden',
    cursor: 'pointer',
    display: 'flex',
    flexDirection: 'column',
    position: 'relative',
    height: '100%',
    transition: 'all 0.3s cubic-bezier(0.4,0,0.2,1)',
    boxShadow: '0 2px 12px rgba(0,0,0,0.04)',
  },
  imageWrapper: {
    width: '100%',
    height: '210px',
    padding: '24px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: '#f8fafc',
    borderBottom: '1px solid #f1f5f9',
  },
  image: {
    maxHeight: '100%',
    maxWidth: '100%',
    objectFit: 'contain',
    transition: 'transform 0.4s cubic-bezier(0.4,0,0.2,1)',
  },
  info: {
    padding: '12px',
    display: 'flex',
    flexDirection: 'column',
    flex: 1,
    gap: '6px',
  },
  name: {
    fontSize: '14px',
    fontWeight: '500',
    color: '#212121',
    lineHeight: '1.4',
    height: '38px',
    overflow: 'hidden',
    display: '-webkit-box',
    WebkitLineClamp: 2,
    WebkitBoxOrient: 'vertical',
  },
  ratingRow: {
    display: 'flex',
    alignItems: 'center',
    gap: '6px',
  },
  reviewsCount: {
    fontSize: '12px',
    color: '#878787',
  },
  priceRow: {
    display: 'flex',
    alignItems: 'baseline',
    gap: '6px',
    marginTop: '2px',
  },
  price: {
    fontSize: '17px',
    fontWeight: '800',
    color: '#0f172a',
    letterSpacing: '-0.3px',
  },
  originalPrice: {
    fontSize: '12px',
    textDecoration: 'line-through',
    color: '#878787',
  },
  discount: {
    fontSize: '12px',
    fontWeight: '600',
    color: '#388e3c',
  },
  rewardBanner: {
    backgroundColor: '#f5f8ff',
    border: '1px dashed #c0d8ff',
    borderRadius: '4px',
    padding: '6px 8px',
    display: 'flex',
    alignItems: 'center',
    gap: '6px',
    marginTop: 'auto',
  },
  rewardText: {
    fontSize: '11px',
    color: '#334155',
    fontWeight: '600',
    lineHeight: '1.2',
  },
  addBtn: {
    background: 'linear-gradient(135deg, #4f46e5 0%, #7c3aed 100%)',
    border: 'none',
    color: 'white',
    borderRadius: '10px',
    padding: '10px 12px',
    fontSize: '13px',
    fontWeight: '700',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '6px',
    marginTop: '10px',
    transition: 'all 0.2s ease',
    boxShadow: '0 4px 12px rgba(79,70,229,0.25)',
  },
};

export default ProductCard;
